/// Timeline playback posture requested by the modeless Sequencer.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum TimelinePreviewPlayback {
    Stopped,
    Paused,
    Playing,
}

/// One immutable Sequencer request sampled by the persistent Scene View preview world.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct TimelinePreviewRequest {
    pub(crate) asset: AssetId,
    pub(crate) document: TimelineDocument,
    pub(crate) tick: engine::timeline::TimelineTick,
    pub(crate) playback: TimelinePreviewPlayback,
    pub(crate) preview_events: bool,
    pub(crate) rate_numerator: i32,
    pub(crate) rate_denominator: u32,
    pub(crate) loop_range: Option<engine::timeline::TimelineLoop>,
}

/// Copied telemetry from the production Timeline runtime inside Scene View.
#[derive(Debug, Clone)]
pub(crate) struct TimelinePreviewStatus {
    pub(crate) tick: engine::timeline::TimelineTick,
    pub(crate) state: engine::timeline::TimelinePlaybackState,
    pub(crate) diagnostics: Vec<String>,
}

